import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TimeSeries_createCopy_TriageGen1Test {

    private TimeSeries series;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
    }

    @Test
    public void testCreateCopy_StartLessThanZero() {
        try {
            series.createCopy(-1, 5);
        } catch (IllegalArgumentException e) {
            assertEquals("Requires start >= 0.", e.getMessage());
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testCreateCopy_EndLessThanStart() {
        try {
            series.createCopy(5, 2);
        } catch (IllegalArgumentException e) {
            assertEquals("Requires start <= end.", e.getMessage());
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testCreateCopy_SuccessEmpty() throws CloneNotSupportedException {
        // Testing the branch where start == end and series is empty
        // Note: The provided source code has a 'if (false)' block which prevents the loop from ever executing.
        // Therefore, the copy will always be an empty series regardless of start/end values,
        // provided start and end are valid indices (though the code doesn't check bounds for the loop,
        // the loop is unreachable).

        TimeSeries copy = series.createCopy(0, 0);

        assertNotNull(copy);
        assertEquals(series.getName(), copy.getName());
        assertEquals(0, copy.getItemCount());
        assertTrue(Double.isNaN(copy.getMinY()));
        assertTrue(Double.isNaN(copy.getMaxY()));
    }

    @Test
    public void testCreateCopy_WithData() throws CloneNotSupportedException {
        // Add data to the original series
        series.add(new Second(100.0));
        series.add(new Second(200.0));

        // Because of the 'if (false)' in the source code, the loop logic is unreachable.
        // The test verifies that the method still returns a valid object with reset Min/Max.
        TimeSeries copy = series.createCopy(0, 1);

        assertNotNull(copy);
        assertEquals(series.getName(), copy.getName());
        // Based on the provided code, copy.data is initialized to a new ArrayList and the loop is skipped
        assertEquals(0, copy.getItemCount());
        assertTrue(Double.isNaN(copy.getMinY()));
        assertTrue(Double.isNaN(copy.getMaxY()));
    }

    @Test
    public void testCreateCopy_CloneNotSupportedException() throws CloneNotSupportedException {
        // This tests the signature capability. 
        // Since TimeSeries inherits from Object and implements Cloneable, 
        // we can't easily force CloneNotSupportedException without mocking 
        // or complex subclassing, but we verify the normal flow.
        TimeSeries copy = series.createCopy(0, 0);
        assertNotNull(copy);
    }
}
